{"modifiedFiles":[],"workingNote":"リポジトリ構成と既存の protocol/rules 実装を確認して、resetFen の追加箇所と公開契約への影響を特定します。"}{"modifiedFiles":[{"path":"src/protocol_adapter.ts","content":"import { createInitialWorld } from "./world";
import { advanceFen1, advanceFen2 } from "./fen/rules";
import { advanceOsk1 } from "./osk/rules";
import { advanceTal1 } from "./tal/rules";
import { advanceVok1, advanceVok2 } from "./vok/rules";
import { advanceZef1, advanceZef2 } from "./zef/rules";

type WorldState = ReturnType<typeof createInitialWorld>;

export interface WorldProtocol<WorldStateHandle = WorldState> {
  reset(): WorldStateHandle;
  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ): { success: true; newState: WorldStateHandle } | { success: false; error: string };
  getEntityState(state: WorldStateHandle, entityDisplayName: string): string;
  toAbstractSnapshot(state: WorldStateHandle): Record<string, string>;
}

const operations: Record<string, (state: WorldState) => WorldState> = {
  advanceVok1,
  advanceVok2,
  advanceZef1,
  advanceZef2,
  advanceTal1,
  advanceOsk1,
  advanceFen1,
  advanceFen2,
};

/** Move Fen from pex back to nim. */
export function resetFen(state: WorldState): WorldState {
  if (state.fen !== "pex") {
    throw new Error("Fen must be 'pex' to reset");
  }
  return { ...state, fen: "nim" };
}

operations.resetFen = resetFen;

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export const protocol: WorldProtocol = {
  reset(): WorldState {
    return createInitialWorld();
  },

  applyOperation(
    state: WorldState,
    operationDisplayName: string
  ): { success: true; newState: WorldState } | { success: false; error: string } {
    const operation = operations[operationDisplayName];
    if (!operation) {
      return {
        success: false,
        error: `Unknown operation: ${operationDisplayName}`,
      };
    }

    try {
      return { success: true, newState: operation(state) };
    } catch (error) {
      return { success: false, error: errorMessage(error) };
    }
  },

  getEntityState(state: WorldState, entityDisplayName: string): string {
    const entityName = entityDisplayName.toLowerCase();
    switch (entityName) {
      case "vok":
        return state.vok;
      case "zef":
        return state.zef;
      case "tal":
        return state.tal;
      case "osk":
        return state.osk;
      case "fen":
        return state.fen;
      default:
        return "";
    }
  },

  toAbstractSnapshot(state: WorldState): Record<string, string> {
    return {
      vok: state.vok,
      zef: state.zef,
      tal: state.tal,
      osk: state.osk,
      fen: state.fen,
    };
  },
};
"}],"workingNote":"protocol に resetFen を登録し、Fen が pex の場合のみ不変更新で nim へ戻すよう実装しました。その他の操作、失敗時のエラー返却、既存の状態参照とスナップショット形式を維持しています。"}

